#!/usr/bin/env python3
"""Summarize only completed, independently validated products; CPU only."""
import os
os.environ['CUDA_VISIBLE_DEVICES']='';os.environ['OPENBLAS_NUM_THREADS']='4'
import json,time,hashlib,re
from pathlib import Path
import numpy as np
R=Path(__file__).resolve().parent;PRI=[0,16,38,41,56,63];D=5120

def read(p):return json.loads(p.read_text())
def write(p,x):
 q=p.with_suffix('.tmp');q.write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False));q.replace(p)
def quant(a):return dict(zip(['min','q25','median','q75','p90','p99','max'],map(float,np.quantile(a,[0,.25,.5,.75,.9,.99,1]))))
def words(v,n=5):return ' / '.join(x['text'].replace('\n','↵').replace('\t','⇥')for x in v[:n])
def tablecell(x):return str(x).replace('|','∣').replace('\n',' ')
def language(s):
 zh=len(re.findall('[\u4e00-\u9fff]',s));en=len(re.findall('[A-Za-z]',s));return {'CJK_characters':zh,'Latin_letters':en,'dominant_script':'zh'if zh>en else'en'if en>zh else'mixed'}
def main():
 post=read(R/'posthoc_validation.json');assert post['complete']and post['source_to_local_sha256_match']
 validation=read(R/'validation.json');assert validation['complete']and len(validation['layers'])==64
 poly=read(R/'polysemy_summary.json');assert len(poly['layers'])==64
 rows=[];allk=[];selected_count=0;steer=[];vocab_metric=[];appendix=['# 单轴语言干预：完整生成文本','贪心32tokens；raw续写，不是chat。每层两个prompt × baseline/±5/clamp；保留截断与全部特殊词元。']
 for l in range(64):
  p=R/f'L{l:02d}';c=read(p/'complete.json');s=read(p/'statistics.json');v=read(p/'vocabulary_readouts.json')['axes'];k=np.asarray(s['stats']['heldout']['excess_kurtosis']);allk.append(k);f=read(p/'native/icalens.json')['layers'][str(l)]['fitting'];axis=s['language_axis'];a=poly['layers'][l]
  for ax in v.values():
   A={w['token_id']for w in ax['vanilla'][:5]};B={w['token_id']for w in ax['jlens_n100'][:5]};vocab_metric.append({'layer':l,'overlap_top5':len(A&B)/5})
  selected_count+=len(v)
  row={'layer':l,'axes':D,'kappa_gt1':int((k>1).sum()),'kappa_gt10':int((k>10).sum()),'kurtosis_quantiles':quant(k),'fit_kappa_gt1':s['stats']['fit']['kappa_gt1'],'fit_kappa_gt10':s['stats']['fit']['kappa_gt10'],'language_axis':axis,'language_delta_fit':s['language_delta_fit'][axis],'language_delta_heldout':s['language_delta_heldout'][axis],'language_same_sign':s['language_delta_fit'][axis]*s['language_delta_heldout'][axis]>0,'language_top5_vanilla':v[str(axis)]['vanilla'][:5],'language_top5_jlens':v[str(axis)]['jlens_n100'][:5],'vocab_selected_axes':len(v),'vocab_top5_overlap_mean':float(np.mean([m['overlap_top5']for m in vocab_metric if m['layer']==l])),'objective_history':f['objective_history'],'polysemy':{name:a['sense_contrasts'][name]['top5_fit_axes'][0]for name in ['bank','apple_en','苹果_zh']},'apple_cross_language_contrast_cosine':a['apple_cross_language_contrast_cosine']}
  rows.append(row)
  if l in PRI:
   g=read(p/'steering.json');runs=g['runs'];r={'layer':l,'axis':g['axis'],'runs':[]}
   appendix+=['',f'## L{l} / C{g["axis"]}']
   for i,vv in enumerate(runs):
    base=runs[(i//4)*4]['generated'];entry={**vv,'changed_vs_baseline':vv['generated']!=base,'script_profile':language(vv['generated']),'baseline_script_profile':language(base)};r['runs'].append(entry);appendix+=['',f'### {vv["prompt"]} · {vv["kind"]} {vv["coordinate_delta"]}','', '```text',vv['generated'],'```']
   steer.append(r)
 representatives=[]
 for l in PRI:
  p=R/f'L{l:02d}';a=read(p/'polysemy_analysis.json');v=read(p/'polysemy_readouts.json')['axes'];ctx=read(p/'contexts_decoded.json')['axes']
  for name,contrast in a['sense_contrasts'].items():
   best=contrast['top5_fit_axes'][0];axis=str(best['axis']);side='positive'if best['A_direction_sign']>0 else'negative';opposite='negative'if side=='positive'else'positive'
   representatives.append({'layer':l,'comparison':name,'positive_label':contrast['positive_label'],'negative_label':contrast['negative_label'],'axis':best['axis'],'probe_evidence':best,'A_readouts':v[axis][side],'B_readouts':v[axis][opposite],'natural_top5_contexts':ctx[axis],'status':'contrast-selected candidate; no semantic purity claim'})
 cat=np.concatenate(allk);changed=sum(v['changed_vs_baseline']for r in steer for v in r['runs']if v['kind']!='baseline');total=sum(v['kind']!='baseline'for r in steer for v in r['runs']);script_flips=sum(v['script_profile']['dominant_script']!=v['baseline_script_profile']['dominant_script']for r in steer for v in r['runs']if v['kind']!='baseline')
 summary={'state':'accepted'if len(rows)==64 else'incomplete','time':time.time(),'model':'Qwen/Qwen3.8-27B-FP8 -> streamed BF16','layers':64,'d_model':D,'component_layer_pairs':D*64,'fit_tokens':200704,'heldout_tokens':51200,'input_audit':read(R/'input_audit.json'),'row_normalize':True,'fastica':{'iterations':50,'algorithm':'parallel/symmetric','fun':'logcosh','seed':367,'matmul_precision':'high','fixed_iterations_not_convergence_guarantee':True},'validation':{'file':'validation.json','validated_layers':64,'maximum_probe_score_recompute_relative_l2':max(x['checks']['probe_scores_recompute_relative_l2']for x in validation['layers']),'maximum_sampled_duality_error':max(x['checks']['sampled_reading_writing_duality_maxabs']for x in validation['layers'])},'heldout':{'kappa_gt1':int((cat>1).sum()),'kappa_gt10':int((cat>10).sum()),'kappa_gt1_fraction':float((cat>1).mean()),'kappa_gt10_fraction':float((cat>10).mean()),'kurtosis_quantiles':quant(cat)},'language_sign_generalized_layers':sum(r['language_same_sign']for r in rows),'vocabulary':{'selected_axis_layer_pairs':selected_count,'mean_top5_overlap_vanilla_jlens':float(np.mean([m['overlap_top5']for m in vocab_metric])),'meaning':'vocabulary ranking change only, not interpretability accuracy'},'polysemy_protocol':'72 synthetic prefixes, six senses, 8 selection and4 heldout per sense; heldout 8 examples per binary comparison; layer axes not aligned IDs','polysemy_best_axis_heldout':{name:{'total_correct_over_64_layers':sum(r['polysemy'][name]['heldout_correct']for r in rows),'total_repeated_layer_case_predictions':64*8,'layers_perfect_8_of8':[r['layer']for r in rows if r['polysemy'][name]['heldout_correct']==8],'heldout_sign_agrees_layers':sum(r['polysemy'][name]['same_sign']for r in rows)}for name in ['bank','apple_en','苹果_zh']},'steering':{'baseline_runs':12,'intervention_runs':total,'changed_text_runs':changed,'dominant_script_flip_runs':script_flips,'script_metric_is_heuristic':True,'by_layer':steer},'qualitative_bilingual_plant_axes':[{'layer':38,'axis':2639},{'layer':41,'axis':828}],'manual_candidate_notes':read(R/'manual_candidates.json'),'representative_concept_candidates':representatives,'posthoc_validation':{'source_to_local_sha256_match':True,'files_compared':post['files_compared']},'manual_validated_semantic_axis_count':None,'manual_count_note':'not estimated from kurtosis or word-list changes; representative candidates only','by_layer':rows,'limitations':['High kurtosis is not a semantic label or statistical independence proof.','Fixed50 does not guarantee convergence.','Heldout natural text retains correlated tokens/windows and source-domain imbalance.','Language split is by source corpus, not per-token language ID; Chinese wiki includes English references.','Word-list comparison is a heuristic writing-direction probe; J-lens operates on raw residuals while ICA pre-normalizes rows.','Synthetic polysemy holdout is small; repeated-layer predictions are not independent samples.','No matched PCA/random-rotation probe baseline; sense classification does not establish unique benefit of ICA.','Language steering tests ±5 and clamp on a selected axis, not dose search or random-control causal localization.']}
 write(R/'summary.json',summary);(R/'steering_full_text.md').write_text('\n'.join(appendix)+'\n')
 report=['# Qwen3.8-27B 中英双语全64层 ICA-Lens 实验报告','',f'完成日期：{time.strftime("%Y-%m-%d %H:%M:%S %z")}。双机各32层；全部0..63层已产出并通过验收。大文件均留在本grocery-haven目录，不放公众号assets。','', '## 结论先行','',f'- 全部 **{D*64:,} 个层-成分对**中，独立自然文本留出κ>1为 **{int((cat>1).sum()):,}（{(cat>1).mean():.2%}）**；κ>10为 **{int((cat>10).sum()):,}（{(cat>10).mean():.2%}）**。这是统计重尾计数，不是“这么多个清晰概念”。',f'- 语言对比拟合选轴后，**{summary["language_sign_generalized_layers"]}/64层**在16组留出平行句上保持同号Δ；具体轴也可能编码标点、位置、句法与语种相关混合特征。',f'- 六个代表层共36次干预，其中 **{changed}次输出文本发生变化（生成预算32 tokens）**；字符主导语种启发式检测翻转 **{script_flips}次**，仅作为人工复核线索，不能把文字变化当作成功概念手术。','- bank/apple/苹果额外72条因果前缀已做全层前向；每义8条选轴/标定，4条独立留出。完整分数、选轴及失败例在polysemy_summary.json、各层polysemy_analysis.json。它证明能跑通词义对比，不证明一个轴纯净承担一种词义。','- 人工抽查发现L38/C2639与L41/C828同时响应中英植物/农业左文，J-lens读出植物、作物、crops等，且中英苹果对比各自选中同轴。这是两层的相近候选特征，不等于两个独立概念，也不是苹果专属轴。','- **未给“清晰中英文语义轴总数”冒领一个精确数字。** 高κ、词表变化、合成对比分类准确都不是人工语义纯度验收。','', '## 1. 设置、公式与安全','', '使用官方icalens0.4.0数值核心。每层5120轴、symmetric FastICA/logcosh/tanh，固定50迭代，seed367；row-L2预处理；FP32拟合、协方差FP64累加、torch matmul precision=high。L0..L63表示64个block的输出，不含embedding，也不是把最终RMSNorm另算一层。','', 'x̂=h/||h||₂；y=C(x̂−c)；x̂≈My+c。C为reading矩阵，M为mixing/writing矩阵。按拟合偏度同时翻C行与M列，使拟合skew非负；保留官方按contrast强度排序的原成分ID。κ=E[(y−μ)⁴]/Var(y)²−3，本文主计数以51200个留出tokens为准。','', '拟合200704 tokens、留出51200 tokens，各split按来源严格中英token配平；英文WikiText-103、中文20231101维基，文档隔离，窗口≤512。拟合英文32篇/中文34篇、留出英文6篇/中文11篇，属于小规模文档池且按流顺序截取，不宣称广泛代表性。同文档不同窗口/相邻tokens仍相关；中文维基的英文参考文献没有逐token清洗，不能叫逐词语言完全均衡。双机使用相同SHA的语料，各自分层拟合。','', '复用meta+逐shard 128×128 FP8块转BF16流式加载；模型进程提取完退出，才启动ICA进程，避免驻留叠加。每子进程启动前MemAvailable≥100GiB，内部22GiB/0.25秒，独立外部20GiB/0.25秒killpg护栏；本机只做CPU验收/汇总，不用3080 GPU。','', '## 2. 全层κ与语言Δ成绩单','', '|层|留出κ>1|留出κ>10|κ中位数|语言轴|拟合Δ|留出Δ|', '|---:|---:|---:|---:|---:|---:|---:|']
 for r in rows:report.append(f'|{r["layer"]}|{r["kappa_gt1"]}|{r["kappa_gt10"]}|{r["kurtosis_quantiles"]["median"]:.2f}|C{r["language_axis"]}|{r["language_delta_fit"]:.2f}|{r["language_delta_heldout"]:.2f}|')
 report+=['','语言Δ为48组拟合平行句mean(y_zh−y_en)，按绝对Δ选轴，在另外16组平行句检验；两语言末尾均显式加同一个换行token，排除了“中英文句号不同”的最直接混淆，但未严格控制长度和句法。编号在各层独立，不能说C105跨层就是同一概念。','', '## 3. bank / apple / 苹果跨层词义对比','', 'bank为银行/河岸，英文apple为水果/公司（公司名也用小写，控制字面大小写），中文苹果为水果/公司。所有样本目标词位于输入末尾，只有左文，没有偷看目标后的消歧句。前缀与固定目标后缀分别编码，保证同语种同词形的目标token序列相同，解码文本不变；是否与整句默认分词一致也逐例留档。每义12条，前8条只选轴/阈值，后4条检验；选择最大的|拟合均值差|轴，不用留出反选层或轴。公司apple统一小写也意味着与自然品牌拼写略有偏离。','', '|层|bank 选轴/留出正确|apple 选轴/留出正确|苹果 选轴/留出正确|英/中水果-公司差向量余弦|','|---:|---|---|---|---:|']
 for r in rows:
  vals=[f'C{r["polysemy"][n]["axis"]} · {r["polysemy"][n]["heldout_correct"]}/8'for n in ['bank','apple_en','苹果_zh']];report.append('|'+str(r['layer'])+'|'+'|'.join(vals)+f'|{r["apple_cross_language_contrast_cosine"]:.3f}|')
 report+=['','这里测的是目标词位置的上下文表征，未单独控制或排除前文主题自身的贡献，不能说是词元本身的一根纯词义开关。这些比率每层只有8个留出实例，未与PCA/随机旋转基底做同口径选轴比较，不能证明ICA独有或更优。不能把64层重复预测凑成512个独立样本；全部跨层值保留，没有只报最漂亮的一层。差向量余弦在同一层ICA坐标内计算，用于观察中英同义对比的一致性，不是跨层轴对齐，也不是严格语义独立性证明。','', '## 4. Vanilla 与 N100 J-lens 词表读出','', '同一writing方向d分别直接读，或先做J_l d，再送实际Qwen Final RMSNorm（1+weight，eps取模型配置）和lm_head。L63为恒等，应两者完全一致，验收已检查。每个原候选轴保存Top20；多义词另存正负两个方向Top20。输出是wordpiece，不能把单token解码碎片当完整词或硬贴人类概念标签。','', f'原候选共{selected_count}个层-轴对；Top5词元集合交集比例均值为{summary["vocabulary"]["mean_top5_overlap_vanilla_jlens"]:.3f}。这是“换镜头后词表变化量”，**不是解释性或正确率提升分数**。J-lens是在原始残差上拟合，ICA对行先归一化；这里是启发式方向读出，不等同对某个基准上下文严格求导并做范数投影后的因果映射。','', '|层/语言候选轴|Vanilla Top5|J-lens Top5|','|---|---|---|']
 for l in PRI:
  r=rows[l];report.append(f'|L{l}/C{r["language_axis"]}|{tablecell(words(r["language_top5_vanilla"]))}|{tablecell(words(r["language_top5_jlens"]))}|')
 report+=['','自然语料最高激活上下文请看各层contexts_decoded.json；它以整个token切片一次解码，修正早期contexts.json逐token拼接可能产生的中文UTF-8替换符。保留老文件作过程记录；任何轴的语义判断以修正后的因果左文、词义探针和正负词表共同核查。','', '## 5. 单轴干预：真实输出与限制','', '只在L0/16/38/41/56/63各自最大拟合语言Δ轴操作。对单位残差做坐标±5或clamp至0，再单位化并恢复原范数；clamp至0指再次单位化之前，不能声称新输出坐标严格为0；重新单位化也会耦合其余ICA坐标，因此这里是沿单轴writing方向的范数保持干预，不是严格只改一个坐标且其余全不动。作用于prompt末位及每一步decode当前末位。无随机轴对照、未扫剂量、不作干预有效率普遍结论。','', '|层|相对baseline改变的干预数/6|字符主导语种翻转/6|','|---:|---:|---:|']
 for r in steer:
  selected=[x for x in r['runs']if x['kind']!='baseline'];report.append(f'|{r["layer"]}|{sum(x["changed_vs_baseline"]for x in selected)}|{sum(x["script_profile"]["dominant_script"]!=x["baseline_script_profile"]["dominant_script"]for x in selected)}|')
 report+=['','全部48条原样生成在[steering_full_text.md](steering_full_text.md)，包括没有变化和不成功输出。以下先给有变化的例子，不冒充每个例子都切换语义：']
 shown=0
 for r in steer:
  for x in r['runs']:
   if x['kind']!='baseline'and x['changed_vs_baseline']and shown<4:
    base=next(v['generated']for v in r['runs']if v['prompt']==x['prompt']and v['kind']=='baseline');report+=['',f'### L{r["layer"]}/C{r["axis"]} · {x["prompt"]} · {x["kind"]} {x["coordinate_delta"]}','','Baseline：','```text',base,'```','干预：','```text',x['generated'],'```'];shown+=1
 report+=['','## 6. 验收、产物与边界','',f'全部64层native/oriented/SAELens adapter所有张量有限，5120×5120形状、50迭代、拟合样本数、每轴κ阈值计数、偏度符号翻转与两机来源已核验；各文件SHA256见validation.json。每层抽32行检验C·M单位阵，最大绝对误差{summary["validation"]["maximum_sampled_duality_error"]:.3g}；完整142个原探针分数CPU重算最大相对L2误差{summary["validation"]["maximum_probe_score_recompute_relative_l2"]:.3g}。前者是抽样双对偶检查，不写成全矩阵误差；后者受GPU高精度模式与CPU浮点实现差异影响。','', '留出大激活在逐层读出完成后按既定策略释放，因此本轮阈值验收从保存的逐轴κ重新计数，未重新抽模型复算全部自然文本四阶矩。用probes.npy作独立坐标重算；完整复跑可按相同语料SHA和脚本重新提取。','', 'native与oriented权重为精确有符号ICA坐标映射。SAELens adapter是单位decoder的正半波ReLU，必须外部先做row-L2，不能当作原始残差直接接入的完整有符号ICA重构。','', '主要文件：summary.json（本文数字源）、validation.json（SHA与数值检查）、polysemy_summary.json（完整跨层词义对比）、Lxx/native/（官方格式）、Lxx/oriented.safetensors、Lxx/statistics.json、Lxx/vocabulary_readouts.json、Lxx/polysemy_readouts.json、Lxx/contexts_decoded.json、Lxx/steering.json（仅6代表层）、steering_full_text.md。','', '清晰概念轴总数尚未按盲法人工标注，不伪造一个总数；本轮交付是全层镜头、统计、候选概念读出与最小因果摸底。']
 (R/'实验报告.md').write_text('\n'.join(report)+'\n')
 print('SUMMARY_COMPLETE',summary['heldout'],summary['steering']['changed_text_runs'],flush=True)
if __name__=='__main__':main()
